(3092786, 434508, 63703, '<td valign="top">Beautiful picture ! I love how it makes you focus on the light amidst all the darkness around. LOVE it !</td>', 'Beautiful picture ! I love how it makes you focus on the light amidst all the darkness around. LOVE it !', '2006-12-06 12:49:43.000000', NULL, 1),
(3092787, 435102, 656, '<td valign="top">Great, tight portrait.  Lovely light, big smile, good catchlights in her eyes.<br/> <br/>A really happy picture.</td>', 'Great, tight portrait.  Lovely light, big smile, good catchlights in her eyes. A really happy picture.', '2006-12-06 12:49:45.000000', NULL, 1),
