(3096806, 433968, 47316, '<td valign="top">I think this could use some more contrast.</td>', 'I think this could use some more contrast.', '2006-12-07 14:35:06.000000', NULL, 1),
(3096808, 435281, 47316, '<td valign="top">Neat take on the egg.</td>', 'Neat take on the egg.', '2006-12-07 14:35:39.000000', NULL, 1),
(3096816, 433923, 47316, '<td valign="top">I am not really getting the significance of the pretzel in the air. Perhaps it would be better to see someone enjoying it.</td>', 'I am not really getting the significance of the pretzel in the air. Perhaps it would be better to see someone enjoying it.', '2006-12-07 14:36:57.000000', NULL, 1),
(3096819, 435235, 47316, '<td valign="top">Cute. Wish the background was a little blurred so there was more focus on her.</td>', 'Cute. Wish the background was a little blurred so there was more focus on her.', '2006-12-07 14:37:53.000000', NULL, 1),
(3096823, 434129, 42100, '<td valign="top">Very cool abstract approach to the challenge.  Love the colors and tones in this photo.  Great job!</td>', 'Very cool abstract approach to the challenge.  Love the colors and tones in this photo.  Great job!', '2006-12-07 14:38:09.000000', NULL, 1),
(3096826, 434670, 47316, '<td valign="top">Looks too processed to me. Especially around the hairline things seem to look smudged.</td>', 'Looks too processed to me. Especially around the hairline things seem to look smudged.', '2006-12-07 14:39:17.000000', NULL, 1),
(3096827, 435073, 42100, '<td valign="top">I like the concept and compsosition of this photo.  The b&amp;w conversion looks great and goes very well.  Well done!</td>', 'I like the concept and compsosition of this photo.  The b&w conversion looks great and goes very well.  Well done!', '2006-12-07 14:39:17.000000', NULL, 1),
(3096832, 434510, 42100, '<td valign="top">Very cool composition and the light is great.  I like the use of grain in this, but it seems almost to heavy though.  Sweet photo!</td>', 'Very cool composition and the light is great.  I like the use of grain in this, but it seems almost to heavy though.  Sweet photo!', '2006-12-07 14:40:48.000000', NULL, 1),
(3096836, 433690, 47316, '<td valign="top">Great shot. I really love the colors.</td>', 'Great shot. I really love the colors.', '2006-12-07 14:41:00.000000', NULL, 1),
(3096838, 435236, 42100, '<td valign="top">Cool composition, I like the use of negative space with this little guy.  Well done!</td>', 'Cool composition, I like the use of negative space with this little guy.  Well done!', '2006-12-07 14:41:21.000000', NULL, 1),
(3096841, 433267, 42100, '<td valign="top">Excellent technicals combined with very cool use of DOF.  Nicely done!</td>', 'Excellent technicals combined with very cool use of DOF.  Nicely done!', '2006-12-07 14:42:06.000000', NULL, 1),
(3096843, 435266, 42100, '<td valign="top">The dried rose is a lovely combination with the pearls and ribbon.  The technicals are all excellent.  You might of left the earrings out, the post look really out of place.</td>', 'The dried rose is a lovely combination with the pearls and ribbon.  The technicals are all excellent.  You might of left the earrings out, the post look really out of place.', '2006-12-07 14:42:10.000000', NULL, 1),
(3096845, 434255, 42100, '<td valign="top">The color is really rich and vibrant isn''t it?  The natural framing works very well.  The technicals are all very good, but something seems missing, something that would really pull me in.</td>', 'The color is really rich and vibrant isn''t it?  The natural framing works very well.  The technicals are all very good, but something seems missing, something that would really pull me in.', '2006-12-07 14:42:17.000000', NULL, 1),
(3096849, 434866, 69350, '<td valign="top">After seeing librodo''s work with this, it''s hard to see this as an original. Good timing!</td>', 'After seeing librodo''s work with this, it''s hard to see this as an original. Good timing!', '2006-12-07 14:43:34.000000', NULL, 1),
(3096850, 433969, 42100, '<td valign="top">I like the concept, but the runner really gets lost in that swirly, busy sky.  Still a very good photograph though!</td>', 'I like the concept, but the runner really gets lost in that swirly, busy sky.  Still a very good photograph though!', '2006-12-07 14:44:23.000000', NULL, 1),
(3096851, 435049, 53316, '<td valign="top">GORGEOUS. This should totally be made into a print.</td>', 'GORGEOUS. This should totally be made into a print.', '2006-12-07 14:44:23.000000', NULL, 1),
(3096857, 434535, 53316, '<td valign="top">As a biology major, I have to give this a good score.. unfortunately I don''t know if it will seem to meet the challenge to others. Good luck.</td>', 'As a biology major, I have to give this a good score.. unfortunately I don''t know if it will seem to meet the challenge to others. Good luck.', '2006-12-07 14:45:58.000000', NULL, 1),
(3096864, 434165, 53316, '<td valign="top">I think I understand the juxtaposition of elements.. contrasting death versus life... but visually it just doesn''t work for me. A decent image nonetheless.</td>', 'I think I understand the juxtaposition of elements.. contrasting death versus life... but visually it just doesn''t work for me. A decent image nonetheless.', '2006-12-07 14:47:30.000000', NULL, 1),
(3096904, 434129, 53316, '<td valign="top">Wonderful abstract.</td>', 'Wonderful abstract.', '2006-12-07 14:56:28.000000', NULL, 1),
(3096923, 435033, 53316, '<td valign="top">This may not be a "DPC friendly" image... no stunning sunsets, rich saturated colors... but it is a perfect entry for this challenge and I like it.  It would be interesting to see it cropped much tighter, to leave out the adult to the left... would have weird, chopped-off hands holding the infant but it might be interesting anyway, or maybe not.</td>', 'This may not be a "DPC friendly" image... no stunning sunsets, rich saturated colors... but it is a perfect entry for this challenge and I like it.  It would be interesting to see it cropped much tighter, to leave out the adult to the left... would have weird, chopped-off hands holding the infant but it might be interesting anyway, or maybe not.', '2006-12-07 15:00:58.000000', NULL, 1),
(3096934, 434218, 53316, '<td valign="top">Aiee, if only the gloves didn''t have the texture (''cause with the texture they seem more cleaning-type gloves and less science-type), this image would be perfect!!</td>', 'Aiee, if only the gloves didn''t have the texture (''cause with the texture they seem more cleaning-type gloves and less science-type), this image would be perfect!!', '2006-12-07 15:02:05.000000', NULL, 1),
(3096948, 434656, 53316, '<td valign="top">Whooooo!</td>', 'Whooooo!', '2006-12-07 15:04:54.000000', NULL, 1),
(3097046, 434165, 40580, '<td valign="top">That''s really funny.  Not a technically good picture, but funny subject.</td>', 'That''s really funny.  Not a technically good picture, but funny subject.', '2006-12-07 15:25:25.000000', NULL, 1),
(3097091, 434161, 67258, '<td valign="top">Now that is what I call living life.  A real sense of vibrancy here. 9</td>', 'Now that is what I call living life.  A real sense of vibrancy here. 9', '2006-12-07 15:37:10.000000', NULL, 1),
(3097095, 435096, 67258, '<td valign="top">What a very clever concept, and well executed, too.  Did you take a series of these? I would be curious to see more with differing shutter speeds.</td>', 'What a very clever concept, and well executed, too.  Did you take a series of these? I would be curious to see more with differing shutter speeds.', '2006-12-07 15:38:22.000000', NULL, 1),
(3097097, 435221, 67258, '<td valign="top">Interesting transposition - well spotted!</td>', 'Interesting transposition - well spotted!', '2006-12-07 15:39:14.000000', NULL, 1),
(3097102, 435208, 67258, '<td valign="top">Sharper focus on the eyes would give this fun portrait greater impact.</td>', 'Sharper focus on the eyes would give this fun portrait greater impact.', '2006-12-07 15:40:07.000000', NULL, 1),
(3097124, 434556, 67258, '<td valign="top">Oh God, that is SOOO cute!  But I shall put my delight in the subject to one side to rate the photo: excelent depth of field, with all the duckling and most of the hands in focus, with the background thrown completely out; good sharp focus on the eye; pleasing composition.  And it is cute...</td>', 'Oh God, that is SOOO cute!  But I shall put my delight in the subject to one side to rate the photo: excelent depth of field, with all the duckling and most of the hands in focus, with the background thrown completely out; good sharp focus on the eye; pleasing composition.  And it is cute...', '2006-12-07 15:44:17.000000', NULL, 1),
(3097130, 434866, 67258, '<td valign="top">10 10 10</td>', '10 10 10', '2006-12-07 15:46:28.000000', NULL, 1),
(3097131, 435033, 67258, '<td valign="top">My goodness, what perfect timing!  Considering how quickly you must have had to take this, I think it is absolutely amazing.  Are you proud parent, or hospital staff?</td>', 'My goodness, what perfect timing!  Considering how quickly you must have had to take this, I think it is absolutely amazing.  Are you proud parent, or hospital staff?', '2006-12-07 15:47:06.000000', NULL, 1),
(3097141, 435096, 36583, '<td valign="top">Stockholm is my guess... Interesting shot.</td>', 'Stockholm is my guess... Interesting shot.', '2006-12-07 15:49:22.000000', NULL, 1),
(3097165, 433923, 67258, '<td valign="top">I simply don''t get this photo - I have returned to it several times in the hope that the penny wil drop, but nope.  The centre column of the object being held up loks a little like a DNA helix, but I suspect I am clutching at straws.</td>', 'I simply don''t get this photo - I have returned to it several times in the hope that the penny wil drop, but nope.  The centre column of the object being held up loks a little like a DNA helix, but I suspect I am clutching at straws.', '2006-12-07 15:53:31.000000', NULL, 1),
(3097177, 435246, 67258, '<td valign="top">I must be missing something here...</td>', 'I must be missing something here...', '2006-12-07 15:57:07.000000', NULL, 1),
(3097186, 434772, 67258, '<td valign="top">Love the photo, but don''t really understand how it relates to the challenge - hopefully your comments will elaborate.</td>', 'Love the photo, but don''t really understand how it relates to the challenge - hopefully your comments will elaborate.', '2006-12-07 15:59:07.000000', NULL, 1),
(3097250, 433018, 53316, '<td valign="top">YAY!</td>', 'YAY!', '2006-12-07 16:14:26.000000', NULL, 1),
(3097280, 434508, 41370, '<td valign="top">Brrrrr....Like the cold feeling!</td>', 'Brrrrr....Like the cold feeling!', '2006-12-07 16:23:24.000000', NULL, 1),
(3097287, 434724, 41370, '<td valign="top">Lighting at the top is a little harsh.  I like the trunk of the plant.  It looks like hips and legs and a waist.</td>', 'Lighting at the top is a little harsh.  I like the trunk of the plant.  It looks like hips and legs and a waist.', '2006-12-07 16:25:51.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3097296, 434218, 41370, '<td valign="top">I like the light on white with just a splash of color.</td>', 'I like the light on white with just a splash of color.', '2006-12-07 16:27:00.000000', NULL, 1),
(3097297, 435008, 50695, '<td valign="top">I think she''s dominating the photo too much, she''s so much bigger and brighter than he is. 6</td>', 'I think she''s dominating the photo too much, she''s so much bigger and brighter than he is. 6', '2006-12-07 16:27:01.000000', NULL, 1),
(3097301, 434685, 41370, '<td valign="top">I like the playfulness and the feel of love.  The sepia is a nice touch.</td>', 'I like the playfulness and the feel of love.  The sepia is a nice touch.', '2006-12-07 16:27:59.000000', NULL, 1),
(3097306, 434742, 41370, '<td valign="top">I like the shallow depth of field and the use of black and white.</td>', 'I like the shallow depth of field and the use of black and white.', '2006-12-07 16:28:58.000000', NULL, 1),
(3097311, 435246, 41370, '<td valign="top">This has a nice abstract feel.  It doesn''t shout "life" to me but the bit of light movement helps.</td>', 'This has a nice abstract feel.  It doesn''t shout "life" to me but the bit of light movement helps.', '2006-12-07 16:30:17.000000', NULL, 1),
(3097314, 434296, 41370, '<td valign="top">Very nice capture.</td>', 'Very nice capture.', '2006-12-07 16:31:24.000000', NULL, 1),
