(3103646, 433969, 55838, '<td valign="top">Just so cool.  Love the sky and the little tiny runner.  Back to bump you up to 9.</td>', 'Just so cool.  Love the sky and the little tiny runner.  Back to bump you up to 9.', '2006-12-10 07:35:02.000000', NULL, 1),
(3103647, 434866, 64068, '<td valign="top">I would have givin it a ten if cropped in a better way and had some clouds.. 8</td>', 'I would have givin it a ten if cropped in a better way and had some clouds.. 8', '2006-12-10 07:35:35.000000', NULL, 1),
(3103650, 434024, 64068, '<td valign="top">I almost feel the needle stick :)</td>', 'I almost feel the needle stick :)', '2006-12-10 07:42:30.000000', NULL, 1),
(3103652, 434170, 61155, '<td valign="top">love her skirt! nice composition on this shot.</td>', 'love her skirt! nice composition on this shot.', '2006-12-10 07:44:41.000000', NULL, 1),
