(3104353, 435001, 49773, '<td valign="top">Wonderful moment and an adorable approach to the challenge. I would''ve even crop it tighter on the left to loose that wall.</td>', 'Wonderful moment and an adorable approach to the challenge. I would''ve even crop it tighter on the left to loose that wall.', '2006-12-10 16:27:56.000000', NULL, 1),
