(3104524, 433018, 33421, '<td valign="top">this is an awesome pic 10</td>', 'this is an awesome pic 10', '2006-12-10 18:01:55.000000', NULL, 1),
(3104631, 433729, 2170, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by nudibranch:</b></div><hr/><i>Hi, thanks for your comment. We have just moved to this area, and I took the pic of the neighbours roses - I don''t think they would appreciated it if I pulled a few leaves off their bush, but I think that is a good idea and I''ll try it sometime. I took this pic on an overcast day which gives nice even lighting.</i></td></tr></table> <br/> <br/>-- this was accidentally posted as a "reported post" to the SC.</td>', 'Originally posted by nudibranch:Hi, thanks for your comment. We have just moved to this area, and I took the pic of the neighbours roses - I don''t think they would appreciated it if I pulled a few leaves off their bush, but I think that is a good idea and I''ll try it sometime. I took this pic on an overcast day which gives nice even lighting.  -- this was accidentally posted as a "reported post" to the SC.', '2006-12-10 19:08:42.000000', NULL, 1),
(3104654, 434524, 62167, '<td valign="top">Nice pic. I like the colours and the water droplets on the lizard, they make it interesting.</td>', 'Nice pic. I like the colours and the water droplets on the lizard, they make it interesting.', '2006-12-10 19:21:59.000000', NULL, 1),
(3104664, 434556, 62167, '<td valign="top">Beautiful, I can just about feel the warmth of the little body in my hands.</td>', 'Beautiful, I can just about feel the warmth of the little body in my hands.', '2006-12-10 19:23:36.000000', NULL, 1),
(3104844, 435244, 56673, '<td valign="top">Can''t tell what this is.</td>', 'Can''t tell what this is.', '2006-12-10 21:02:27.000000', NULL, 1),
