(3104952, 434430, 34938, '<td valign="top">clever and quirky...I like the lighting</td>', 'clever and quirky...I like the lighting', '2006-12-10 22:12:47.000000', NULL, 1),
(3104954, 434362, 34938, '<td valign="top">he''s such a good looking dog! as a picture, perhaps there is a little bit of blur which spoils the shot, but it''s spontaneous and full of life</td>', 'he''s such a good looking dog! as a picture, perhaps there is a little bit of blur which spoils the shot, but it''s spontaneous and full of life', '2006-12-10 22:14:24.000000', NULL, 1),
(3104958, 434556, 34938, '<td valign="top">nice image...would have liked to have seen the whole thumb, but that''s minor, very good</td>', 'nice image...would have liked to have seen the whole thumb, but that''s minor, very good', '2006-12-10 22:16:09.000000', NULL, 1),
(3104961, 435232, 34938, '<td valign="top">OK...want to be kind here but there are a couple of distractions...the hair at the base of the wrist, the little bit of grit on the thumbnail...it''s a nice image overall, but these things let it down</td>', 'OK...want to be kind here but there are a couple of distractions...the hair at the base of the wrist, the little bit of grit on the thumbnail...it''s a nice image overall, but these things let it down', '2006-12-10 22:18:42.000000', NULL, 1),
