(3105017, 434293, 67694, '<td valign="top">I didn''t know the Fritillary caterpillar was deadly :) nice capture</td>', 'I didn''t know the Fritillary caterpillar was deadly :) nice capture', '2006-12-10 22:59:19.000000', NULL, 1),
(3105022, 434274, 67694, '<td valign="top">I love the title and the photo</td>', 'I love the title and the photo', '2006-12-10 23:00:56.000000', NULL, 1),
(3105023, 433823, 67694, '<td valign="top">not enough in focus for me.  I can''t make out what the gift is.</td>', 'not enough in focus for me.  I can''t make out what the gift is.', '2006-12-10 23:02:00.000000', NULL, 1),
(3105067, 434218, 62477, '<td valign="top">Creative and well-framed. And I like how there''s a pattern in the background (versus just having a plain background). Same goes for the gloves. Nicely done.</td>', 'Creative and well-framed. And I like how there''s a pattern in the background (versus just having a plain background). Same goes for the gloves. Nicely done.', '2006-12-10 23:27:20.000000', NULL, 1),
(3105482, 434670, 34113, '<td valign="top">Exquisite portrait.</td>', 'Exquisite portrait.', '2006-12-11 01:28:47.000000', NULL, 1),
