(3105975, 434528, 67671, '<td valign="top">looks like new growth after a fire, love the colors.</td>', 'looks like new growth after a fire, love the colors.', '2006-12-11 09:57:01.000000', NULL, 1),
(3106001, 434853, 67671, '<td valign="top">seems to be a lot of dark areas, and some harsh shadows, love the bikes though, good luck, and safe biking.</td>', 'seems to be a lot of dark areas, and some harsh shadows, love the bikes though, good luck, and safe biking.', '2006-12-11 10:06:23.000000', NULL, 1),
(3106025, 435211, 67671, '<td valign="top">at first glance it looks as though it was taken through the greenhouse window, and the water drops are on the glass, could get some low votes from those who don''t look propperly, nice capture, and good luck.</td>', 'at first glance it looks as though it was taken through the greenhouse window, and the water drops are on the glass, could get some low votes from those who don''t look propperly, nice capture, and good luck.', '2006-12-11 10:17:54.000000', NULL, 1),
(3106035, 435097, 67671, '<td valign="top">great idea, let down a little by the focus, the egg is sharper than the young lad, DOF not quite deep enough, nicely lined up, and framed.</td>', 'great idea, let down a little by the focus, the egg is sharper than the young lad, DOF not quite deep enough, nicely lined up, and framed.', '2006-12-11 10:24:29.000000', NULL, 1),
(3106042, 434643, 67671, '<td valign="top">is that the bird talking, or you, saying got the shot, realy good one at that, frame, focus, colors, all good.</td>', 'is that the bird talking, or you, saying got the shot, realy good one at that, frame, focus, colors, all good.', '2006-12-11 10:30:53.000000', NULL, 1),
(3106058, 433904, 67671, '<td valign="top">the onley thing I don''t like about this shot, is that black frame around it, it''s just so distracting.</td>', 'the onley thing I don''t like about this shot, is that black frame around it, it''s just so distracting.', '2006-12-11 10:34:37.000000', NULL, 1),
(3106064, 433969, 68256, '<td valign="top">Great capture!  That sky really has texture huh?   It is almost too much texture for me and I kinda loose the little guy running for his life.  Overall great interpretation and presentation.</td>', 'Great capture!  That sky really has texture huh?   It is almost too much texture for me and I kinda loose the little guy running for his life.  Overall great interpretation and presentation.', '2006-12-11 10:35:22.000000', NULL, 1),
(3106083, 434556, 68256, '<td valign="top">Nice picture.  I know it is basic editing and you couldn''t have done this, but selective sharpening would really be neat I think.  Keep the feathers soft and the eye/bill sharper?  Anyway I''m obviously not lowering the score because of that, just a thought.</td>', 'Nice picture.  I know it is basic editing and you couldn''t have done this, but selective sharpening would really be neat I think.  Keep the feathers soft and the eye/bill sharper?  Anyway I''m obviously not lowering the score because of that, just a thought.', '2006-12-11 10:38:37.000000', NULL, 1),
(3106104, 434218, 68256, '<td valign="top">Good job, everything is clean and well composed.</td>', 'Good job, everything is clean and well composed.', '2006-12-11 10:44:33.000000', NULL, 1),
