(3109996, 434024, 66456, '<td valign="top">A nice twist on the theme...</td>', 'A nice twist on the theme...', '2006-12-12 18:40:50.000000', NULL, 1),
(3110137, 434680, 41370, '<td valign="top">The focus doesn''t seem sharp enough.</td>', 'The focus doesn''t seem sharp enough.', '2006-12-12 19:18:31.000000', NULL, 1),
(3110150, 435097, 41370, '<td valign="top">Very clever, nice color.</td>', 'Very clever, nice color.', '2006-12-12 19:21:17.000000', NULL, 1),
(3110170, 435096, 35804, '<td valign="top">Great vibe...love the frantic pace of this.</td>', 'Great vibe...love the frantic pace of this.', '2006-12-12 19:28:05.000000', NULL, 1),
(3110183, 435160, 35804, '<td valign="top">There is such a worn, exhausted elegance about this...I suppose much like the city itself, glimpses of what used to be and what still is...very nice.</td>', 'There is such a worn, exhausted elegance about this...I suppose much like the city itself, glimpses of what used to be and what still is...very nice.', '2006-12-12 19:33:21.000000', NULL, 1),
(3110191, 435168, 66597, '<td valign="top">The containers you selected are interesting. The lighting could be stronger IMO.</td>', 'The containers you selected are interesting. The lighting could be stronger IMO.', '2006-12-12 19:35:27.000000', NULL, 1),
(3110193, 434165, 66597, '<td valign="top">Definitely out of the box. The composition could be a bit stronger, but an interesting shot nonetheless. 6.</td>', 'Definitely out of the box. The composition could be a bit stronger, but an interesting shot nonetheless. 6.', '2006-12-12 19:35:44.000000', NULL, 1),
(3110194, 434074, 66597, '<td valign="top">Nice composition and reflections. Wonder if it could be a bit sharper.</td>', 'Nice composition and reflections. Wonder if it could be a bit sharper.', '2006-12-12 19:35:56.000000', NULL, 1),
(3110197, 435096, 66597, '<td valign="top">This one is nicely out of the box. Wish it were a bit less grainy in the background.</td>', 'This one is nicely out of the box. Wish it were a bit less grainy in the background.', '2006-12-12 19:36:45.000000', NULL, 1),
(3110201, 434274, 66597, '<td valign="top">I really like the curve of the road. The position of the boy seems a bit off in terms of composition, and the cut-off shadow drew my eyes out to the right. 6.</td>', 'I really like the curve of the road. The position of the boy seems a bit off in terms of composition, and the cut-off shadow drew my eyes out to the right. 6.', '2006-12-12 19:37:35.000000', NULL, 1),
(3110205, 434067, 66597, '<td valign="top">Even though this looks processed to death and has an obviously skewed horizon, there is something captivating about it. 6.</td>', 'Even though this looks processed to death and has an obviously skewed horizon, there is something captivating about it. 6.', '2006-12-12 19:38:37.000000', NULL, 1),
(3110206, 435034, 66597, '<td valign="top">I love the greens in this shot, but the browns look like a bit washed out (maybe too much desat in that area or heavy-handed with the shadows/highlights tool?) Composition is a bit ordinary as well.</td>', 'I love the greens in this shot, but the browns look like a bit washed out (maybe too much desat in that area or heavy-handed with the shadows/highlights tool?) Composition is a bit ordinary as well.', '2006-12-12 19:38:40.000000', NULL, 1),
(3110207, 433923, 35804, '<td valign="top">...and people think the cheese steak is the official food of Philly...</td>', '...and people think the cheese steak is the official food of Philly...', '2006-12-12 19:38:51.000000', NULL, 1),
(3110208, 433968, 66597, '<td valign="top">The silhouette is very strong. The background, however, looks grainy and detracts IMO. 6.</td>', 'The silhouette is very strong. The background, however, looks grainy and detracts IMO. 6.', '2006-12-12 19:39:04.000000', NULL, 1),
(3110212, 434643, 66597, '<td valign="top">Although this compositionally could be a bit stronger, it is a great capture with splendid colors. 6.</td>', 'Although this compositionally could be a bit stronger, it is a great capture with splendid colors. 6.', '2006-12-12 19:39:37.000000', NULL, 1),
(3110214, 435331, 66597, '<td valign="top">The composition is strong, and most of the whites are not blown, which looks difficult. Doesn''t hold my interest too well, however. 5.</td>', 'The composition is strong, and most of the whites are not blown, which looks difficult. Doesn''t hold my interest too well, however. 5.', '2006-12-12 19:40:32.000000', NULL, 1),
(3110217, 434643, 35804, '<td valign="top">Yes you did! Fantastic catch! Beautiful light and bokeh.</td>', 'Yes you did! Fantastic catch! Beautiful light and bokeh.', '2006-12-12 19:41:10.000000', NULL, 1),
(3110219, 435266, 66597, '<td valign="top">Very good lighting on those crisp whites. I like the look of selective desat here with just the faintly colored rose(even though there isn''t desat in this photo). 6.</td>', 'Very good lighting on those crisp whites. I like the look of selective desat here with just the faintly colored rose(even though there isn''t desat in this photo). 6.', '2006-12-12 19:41:29.000000', NULL, 1),
(3110220, 435244, 66597, '<td valign="top">This is a daring entry that took a moment before the little lightbulb went off in my head :-) I''m having trouble seeing the whole photo on my monitor in one go, so it''s tough to say whether or not the composition works IMO. It definitely works on the level of making the viewer stop and think. Is it art? Who is qualified to say? 6.</td>', 'This is a daring entry that took a moment before the little lightbulb went off in my head :-) I''m having trouble seeing the whole photo on my monitor in one go, so it''s tough to say whether or not the composition works IMO. It definitely works on the level of making the viewer stop and think. Is it art? Who is qualified to say? 6.', '2006-12-12 19:41:44.000000', NULL, 1),
(3110225, 435208, 66597, '<td valign="top">Really like the expression and soft lighting. I think it would be stronger overall with just a bit more breathing room to the left of the child''s face. 6.</td>', 'Really like the expression and soft lighting. I think it would be stronger overall with just a bit more breathing room to the left of the child''s face. 6.', '2006-12-12 19:42:22.000000', NULL, 1),
(3110226, 435001, 35804, '<td valign="top">Ah! Excellent!</td>', 'Ah! Excellent!', '2006-12-12 19:42:58.000000', NULL, 1),
(3110227, 434210, 66597, '<td valign="top">I like the selective desat in this photo, as it has a reason. Not sure how you pulled it off in basic, but the photo was validated, so you obviously did. 6.</td>', 'I like the selective desat in this photo, as it has a reason. Not sure how you pulled it off in basic, but the photo was validated, so you obviously did. 6.', '2006-12-12 19:43:21.000000', NULL, 1),
(3110230, 433960, 66597, '<td valign="top">The warm lighting adds strength to this photo, and the composition is strong. The pole on the left side of the pier is distracting (realize you couldn''t clone it out in basic, however). 6.</td>', 'The warm lighting adds strength to this photo, and the composition is strong. The pole on the left side of the pier is distracting (realize you couldn''t clone it out in basic, however). 6.', '2006-12-12 19:44:08.000000', NULL, 1),
