INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3110951, 433018, 42567, '<td valign="top">Great picture Tim!  One of my fav''s during the challenge!</td>', 'Great picture Tim!  One of my fav''s during the challenge!', '2006-12-13 00:27:49.000000', NULL, 0),
(3110963, 435001, 48890, '<td valign="top">Yay, finally, a real art photograph in the top 10.  This should have won, of course.</td>', 'Yay, finally, a real art photograph in the top 10.  This should have won, of course.', '2006-12-13 00:29:17.000000', NULL, 0),
(3110970, 433969, 53147, '<td valign="top">Well done Phil! Beautiful image, excellent score, perfect ribbon color!</td>', 'Well done Phil! Beautiful image, excellent score, perfect ribbon color!', '2006-12-13 00:30:32.000000', NULL, 0),
(3110971, 435246, 53316, '<td valign="top">Well, I have to say I kind of wavered back and forth about the score throughout the week.  I liked the image; there was never any question about that.  Noise... geez, what''s wrong with grain like this in an abstract?  Beautiful colors, a strong visual subject in the lower left so that the eye does not wander, the image in the background of power lines but are we certain that''s what they are.. all combine to create a beautiful piece of art.  I just did not know if it related to the challenge for me.  In the end though, I felt that it did.  This may not be what you were going for, but it was my take on it: The yellow/orange light is the individual (or the two married who are now one flesh) - reaching out and holding strong against the colder, harsher outside world.  That definitely relates to the challenge for me, and in the end, I gave it a score that I really would have loved more than three people to give as well.</td>', 'Well, I have to say I kind of wavered back and forth about the score throughout the week.  I liked the image; there was never any question about that.  Noise... geez, what''s wrong with grain like this in an abstract?  Beautiful colors, a strong visual subject in the lower left so that the eye does not wander, the image in the background of power lines but are we certain that''s what they are.. all combine to create a beautiful piece of art.  I just did not know if it related to the challenge for me.  In the end though, I felt that it did.  This may not be what you were going for, but it was my take on it: The yellow/orange light is the individual (or the two married who are now one flesh) - reaching out and holding strong against the colder, harsher outside world.  That definitely relates to the challenge for me, and in the end, I gave it a score that I really would have loved more than three people to give as well.', '2006-12-13 00:30:44.000000', NULL, 0),
(3110993, 433969, 36371, '<td valign="top">Hey Mr. Kentucky Boy!! Way to Go!! Gorgeous Ky sky! And taken on my birthday, too! Thanks!<br/><br/><i>Message edited by author 2006-12-13 00:33:38.</i></td>', 'Hey Mr. Kentucky Boy!! Way to Go!! Gorgeous Ky sky! And taken on my birthday, too! Thanks!', '2006-12-13 00:33:06.000000', '2006-12-13 00:33:38.000000', 0),
(3110999, 435246, 48890, '<td valign="top">Oh, no, a brown one! :)  Is this your first?  You were asking for it with this shot, though, but you know it.  Next time shoot your dog inside a light bulb, and you should do better. :)</td>', 'Oh, no, a brown one! :)  Is this your first?  You were asking for it with this shot, though, but you know it.  Next time shoot your dog inside a light bulb, and you should do better. :)', '2006-12-13 00:33:59.000000', NULL, 0),
(3111016, 435246, 60862, '<td valign="top">Interesting piece of art there, Don.  Well, first let me congratulate you on knocking off your goal of getting the brown without trying. :)<br/> <br/>As to the image, I do like it as an abstract.  I find that the large grain makes it look almost like a pointillist painting, and I''ve always liked those.<br/> <br/>As to how it relates to the concept of life, I have to admit I''m scratching my head.</td>', 'Interesting piece of art there, Don.  Well, first let me congratulate you on knocking off your goal of getting the brown without trying. :) As to the image, I do like it as an abstract.  I find that the large grain makes it look almost like a pointillist painting, and I''ve always liked those. As to how it relates to the concept of life, I have to admit I''m scratching my head.', '2006-12-13 00:35:35.000000', NULL, 0),
(3111027, 435282, 48890, '<td valign="top">Why would anyone want to shoot something like this (provided there were no compensation), is beyond me.  This got a 4 from me.</td>', 'Why would anyone want to shoot something like this (provided there were no compensation), is beyond me.  This got a 4 from me.', '2006-12-13 00:36:45.000000', NULL, 0),
(3111040, 434024, 67189, '<td valign="top">Thank you for great comments. I was not sure how well it would place but I am happy with the end result. This was only my second time working with lighting and trying to get a well controlled outcome. I am not that creative a person so I most likely will not score well untill I can develop some sort of creative style. My main point with this was to work from a technical aspect and create an image with some positive things such as lighting and working with DOF to create a focal point.</td>', 'Thank you for great comments. I was not sure how well it would place but I am happy with the end result. This was only my second time working with lighting and trying to get a well controlled outcome. I am not that creative a person so I most likely will not score well untill I can develop some sort of creative style. My main point with this was to work from a technical aspect and create an image with some positive things such as lighting and working with DOF to create a focal point.', '2006-12-13 00:38:37.000000', NULL, 0),
(3111047, 434362, 60862, '<td valign="top">Very nice capture. :)  As you already know, it''s the focus that held the score back.  If you can, try turning off the multi-zone focus and just focus on the center spot, then point that at eyes.  Everyone tends to jump right to the eyes, and when they''re not sharp, the rest of it seems less sharp.<br/> <br/>But of course, when shooting fast-moving targets, you take what you can get, and this is a very fun shot! :)</td>', 'Very nice capture. :)  As you already know, it''s the focus that held the score back.  If you can, try turning off the multi-zone focus and just focus on the center spot, then point that at eyes.  Everyone tends to jump right to the eyes, and when they''re not sharp, the rest of it seems less sharp. But of course, when shooting fast-moving targets, you take what you can get, and this is a very fun shot! :)', '2006-12-13 00:39:22.000000', NULL, 0),
(3111052, 433969, 36988, '<td valign="top">Phil... This is simply breathtaking. Congrats on a more than well deserved ribbon.</td>', 'Phil... This is simply breathtaking. Congrats on a more than well deserved ribbon.', '2006-12-13 00:40:07.000000', NULL, 0),
