INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3122016, 434556, 48228, '<td valign="top">I found my sparkle, it was there all the time, just hidden from view for awhile. <br/>My little star, beside my little duckling, makes me very happy.....<br/>Thank you everyone.....<br/> <br/>Thanks everyone for the wonderful comments, and huge support you all give me..... <br/> <br/>I am truely blessed each and everyday for DPC and it wonderful members.....</td>', 'I found my sparkle, it was there all the time, just hidden from view for awhile. My little star, beside my little duckling, makes me very happy.....Thank you everyone..... Thanks everyone for the wonderful comments, and huge support you all give me.....  I am truely blessed each and everyday for DPC and it wonderful members.....', '2006-12-15 19:17:53.000000', NULL, 0),
(3122094, 434556, 43714, '<td valign="top">Way to go SISTER, such a sweet shot, I think I know those hands.. great choice for the challenge!!</td>', 'Way to go SISTER, such a sweet shot, I think I know those hands.. great choice for the challenge!!', '2006-12-15 19:47:11.000000', NULL, 0),
